const item = $input.first();
const stdout = String(item.json.stdout || '');
const stderr = String(item.json.stderr || '');
const exitCode = Number(item.json.exitCode ?? 0);
const commandError = item.json.error || null;

function tryParseJson(value) {
  if (!value || !value.trim()) return null;
  try {
    return JSON.parse(value);
  } catch {
    const line = value.split('\\n').find((l) => l.trim().startsWith('{') && l.trim().endsWith('}'));
    if (!line) return null;
    try {
      return JSON.parse(line);
    } catch {
      return null;
    }
  }
}

let payload = tryParseJson(stdout);
if (!payload) {
  payload = {
    status: 'error',
    transcript_text: '',
    source: 'none',
    error: {
      message: commandError?.message || 'Playwright script did not return valid JSON output',
      stack: commandError?.stack || ''
    },
    debug: {
      stage: 'n8n_parse_stdout',
      stdout_preview: stdout.slice(0, 4000),
      stderr_preview: stderr.slice(0, 4000),
      exit_code: exitCode
    }
  };
}

if (typeof payload !== 'object' || payload === null) {
  payload = {
    status: 'error',
    transcript_text: '',
    source: 'none',
    error: { message: 'Playwright script returned non-object payload', stack: '' },
    debug: { stage: 'n8n_payload_validation', exit_code: exitCode }
  };
}

payload.status = String(payload.status || 'error');
payload.transcript_text = String(payload.transcript_text || '');
payload.source = String(payload.source || 'none');
payload.error = payload.error || {};
payload.error.message = String(payload.error.message || '');
payload.error.stack = String(payload.error.stack || '');
payload.debug = payload.debug || {};
payload.debug.exit_code = exitCode;
if (stderr && !payload.debug.stderr_preview) payload.debug.stderr_preview = stderr.slice(0, 4000);
if (stdout && !payload.debug.stdout_preview) payload.debug.stdout_preview = stdout.slice(0, 4000);

return [{ json: payload }];
